const fn export(dll: &[u8], func: &[u8], addr: *const ()) -> Win32ExportEntry {
    const fn padded<const N: usize>(bytes: &[u8]) -> [u8; N] {
        let mut field = [0; N];
        let mut index = 0;
        while index < bytes.len() {
            field[index] = bytes[index];
            index += 1;
        }
        field
    }
    Win32ExportEntry { dll: padded(dll), func: padded(func), addr }
}

#[inline(never)]
pub fn resolve_win32_symbol(dll: &str, func: &str) -> Option<usize> {
    for entry in &WIN32_EXPORTS {
        let entry_dll = core::str::from_utf8(&entry.dll).unwrap_or("").trim_end_matches('\0');
        let entry_func = core::str::from_utf8(&entry.func).unwrap_or("").trim_end_matches('\0');
        if entry_dll.eq_ignore_ascii_case(dll) && entry_func == func {
            return Some(entry.addr as usize);
        }
    }
    None
}
